package com.bank.qa.pyramid;

import java.math.BigDecimal;

// Minimal transfer logic used as the system under test.
class AccountService {
    private BigDecimal rajesh = new BigDecimal("1000000"); // SAV2001
    private BigDecimal priya  = new BigDecimal("250000");  // CUR3001

    // Functional behavior: debit then credit, reject overdraft.
    boolean transfer(BigDecimal amount) {
        if (amount.signum() <= 0) return false;
        if (rajesh.compareTo(amount) < 0) return false; // insufficient funds
        rajesh = rajesh.subtract(amount);
        priya = priya.add(amount);
        return true;
    }

    BigDecimal rajeshBalance() { return rajesh; }
    BigDecimal priyaBalance() { return priya; }
}
