package com.bank.qa.pyramid;

import java.util.function.BooleanSupplier;

// A test tagged with its pyramid level and whether it is functional.
class LeveledTest {
    private final String name;
    private final TestLevel level;
    private final boolean functional;   // false => non-functional (perf/sec)
    private final BooleanSupplier check;

    LeveledTest(String name, TestLevel level, boolean functional, BooleanSupplier check) {
        this.name = name; this.level = level;
        this.functional = functional; this.check = check;
    }

    String getName() { return name; }
    TestLevel getLevel() { return level; }
    boolean isFunctional() { return functional; }
    boolean run() { return check.getAsBoolean(); }
}
