package com.bank.qa.pyramid;

import java.util.*;
import java.util.logging.Logger;

// Counts tests per level and warns if the shape is an ice-cream cone.
class PyramidAnalyzer {
    private static final Logger log = Logger.getLogger(PyramidAnalyzer.class.getName());

    void analyze(List<LeveledTest> tests) {
        Map<TestLevel, Integer> counts = new EnumMap<>(TestLevel.class);
        for (TestLevel l : TestLevel.values()) counts.put(l, 0);
        for (LeveledTest t : tests) counts.merge(t.getLevel(), 1, Integer::sum);

        counts.forEach((level, n) -> log.info(level + ": " + n + " tests"));

        int units = counts.get(TestLevel.UNIT);
        int e2e = counts.get(TestLevel.E2E);
        if (units >= e2e * 2) {
            log.info("Healthy PYRAMID: wide unit base, thin E2E top.");
        } else {
            log.warning("ICE-CREAM CONE anti-pattern: too few unit tests, "
                    + "too many slow E2E tests. Feedback is slow and brittle.");
        }
    }
}
